using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Telemetry-mode evaluations: captures OpenTelemetry traces for each scenario
/// and verifies spans are emitted correctly.
/// </summary>
public class TelemetryEval : IDisposable
{
    private static readonly ActivitySource Source = new("MyApp.Eval.Telemetry");

    private readonly TracerProvider _tracer;
    private readonly List<Activity> _exportedActivities = new();

    public TelemetryEval()
    {
        _tracer = Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Eval"))
            .AddSource("MyApp.Eval.Telemetry")
            .AddSource("Microsoft.Extensions.AI")
            .AddInMemoryExporter(_exportedActivities)
            .Build()!;
    }

    [Fact]
    public async Task Chat_emits_telemetry_spans()
    {
        using var activity = Source.StartActivity("eval.telemetry.chat");

        var client = CreateChatClient();
        var response = await client.GetResponseAsync("What is 2+2?");

        _tracer.ForceFlush();

        Assert.NotEmpty(_exportedActivities);
        Assert.Contains(_exportedActivities, a => a.OperationName.Contains("chat", StringComparison.OrdinalIgnoreCase));
    }

    [Fact]
    public async Task Chat_records_token_usage_in_spans()
    {
        using var activity = Source.StartActivity("eval.telemetry.tokens");

        var client = CreateChatClient();
        var response = await client.GetResponseAsync("Say hello.");

        _tracer.ForceFlush();

        var chatActivity = _exportedActivities
            .FirstOrDefault(a => a.OperationName.Contains("chat", StringComparison.OrdinalIgnoreCase));

        Assert.NotNull(chatActivity);
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "gpt-4o-mini";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient()
            .AsBuilder()
            .UseOpenTelemetry()
            .Build();
    }

    public void Dispose()
    {
        _tracer.Dispose();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Quality-mode evaluations: measures coherence, relevance, and groundedness
/// of chat responses using AI-assisted judges.
/// </summary>
public class QualityEval
{
    private static readonly string ReportDir =
        Path.Combine(Path.GetTempPath(), "MyApp.Eval", "quality-reports");

    [Fact]
    public async Task Response_meets_coherence_threshold()
    {
        var scenario = CreateScenario(
            "coherence-check",
            "You are a helpful coding coach.",
            "Explain what a variable is in C#.");

        var (evaluators, reportingConfig) = SetupEvaluators();

        await using var reporter = await ReportingChatClient.CreateAsync(reportingConfig, scenario);
        var client = CreateJudgeChatClient(reporter);

        var response = await client.GetResponseAsync(scenario.ChatMessages);
        var results = await reporter.EvaluateAsync(response);

        Assert.True(results.All(r => r.Value.Rating >= EvaluationRating.Good),
            "Response did not meet coherence threshold.");
    }

    [Fact]
    public async Task Response_is_relevant_to_prompt()
    {
        var scenario = CreateScenario(
            "relevance-check",
            "You are a helpful coding coach.",
            "What is the difference between a class and a struct in C#?");

        var (evaluators, reportingConfig) = SetupEvaluators();

        await using var reporter = await ReportingChatClient.CreateAsync(reportingConfig, scenario);
        var client = CreateJudgeChatClient(reporter);

        var response = await client.GetResponseAsync(scenario.ChatMessages);
        var results = await reporter.EvaluateAsync(response);

        Assert.True(results.All(r => r.Value.Rating >= EvaluationRating.Good),
            "Response was not relevant to the prompt.");
    }

    [Fact]
    public async Task Response_is_grounded_in_context()
    {
        var context = "C# is a statically typed language created by Microsoft. It supports OOP.";

        var scenario = CreateScenario(
            "groundedness-check",
            $"You are a coding coach. Use only this context: {context}",
            "Is C# dynamically typed?");

        var (evaluators, reportingConfig) = SetupEvaluators();

        await using var reporter = await ReportingChatClient.CreateAsync(reportingConfig, scenario);
        var client = CreateJudgeChatClient(reporter);

        var response = await client.GetResponseAsync(scenario.ChatMessages);
        var results = await reporter.EvaluateAsync(response);

        Assert.True(results.All(r => r.Value.Rating >= EvaluationRating.Good),
            "Response was not grounded in the provided context.");
    }

    private static ChatScenario CreateScenario(string name, string systemPrompt, string userMessage)
    {
        return new ChatScenario(name)
        {
            ChatMessages =
            [
                new ChatMessage(ChatRole.System, systemPrompt),
                new ChatMessage(ChatRole.User, userMessage)
            ]
        };
    }

    private static (IList<IEvaluator> Evaluators, ReportingConfiguration Config) SetupEvaluators()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new GroundednessEvaluator()
        };

        var storage = new DiskBasedReportingStorage(ReportDir);
        var config = new ReportingConfiguration(
            evaluators,
            CreateJudgeChatClient,
            storage);

        return (evaluators, config);
    }

    private static IChatClient CreateJudgeChatClient(IChatClient? innerClient = null)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "gpt-4o-mini";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Compare-mode evaluations: runs the same scenarios against two model
/// configurations and compares quality scores side-by-side.
/// </summary>
public class CompareEval
{
    private static readonly string ReportDir =
        Path.Combine(Path.GetTempPath(), "MyApp.Eval", "compare-reports");

    private static readonly string[] Prompts =
    [
        "Explain dependency injection in one paragraph.",
        "What are the SOLID principles?",
        "Write a simple C# record type example."
    ];

    [Fact]
    public async Task Baseline_vs_candidate_quality_comparison()
    {
        var baselineResults = await RunSuite("baseline", GetBaselineClient);
        var candidateResults = await RunSuite("candidate", GetCandidateClient);

        // Both suites must produce results for all prompts
        Assert.Equal(Prompts.Length, baselineResults.Count);
        Assert.Equal(Prompts.Length, candidateResults.Count);

        // Candidate should not regress below baseline
        for (int i = 0; i < Prompts.Length; i++)
        {
            var baselineScore = AverageRating(baselineResults[i]);
            var candidateScore = AverageRating(candidateResults[i]);

            Assert.True(candidateScore >= baselineScore - 1,
                $"Candidate regressed on prompt {i}: baseline={baselineScore}, candidate={candidateScore}");
        }
    }

    [Fact]
    public async Task Compare_response_lengths()
    {
        var baselineResponses = await CollectResponses(GetBaselineClient);
        var candidateResponses = await CollectResponses(GetCandidateClient);

        for (int i = 0; i < Prompts.Length; i++)
        {
            // Candidate should not be excessively verbose (< 3x baseline length)
            Assert.True(candidateResponses[i].Length <= baselineResponses[i].Length * 3,
                $"Candidate response for prompt {i} is excessively long.");
        }
    }

    private static async Task<List<Dictionary<string, EvaluationResult>>> RunSuite(
        string label,
        Func<IChatClient> clientFactory)
    {
        var results = new List<Dictionary<string, EvaluationResult>>();
        var evaluators = new IEvaluator[] { new CoherenceEvaluator(), new RelevanceEvaluator() };
        var storage = new DiskBasedReportingStorage(Path.Combine(ReportDir, label));
        var config = new ReportingConfiguration(evaluators, CreateJudgeClient, storage);

        foreach (var prompt in Prompts)
        {
            var scenario = new ChatScenario($"{label}-{prompt[..20]}")
            {
                ChatMessages =
                [
                    new ChatMessage(ChatRole.System, "You are a helpful coding coach."),
                    new ChatMessage(ChatRole.User, prompt)
                ]
            };

            await using var reporter = await ReportingChatClient.CreateAsync(config, scenario);
            var client = clientFactory();
            var response = await client.GetResponseAsync(scenario.ChatMessages);
            var evalResult = await reporter.EvaluateAsync(response);
            results.Add(evalResult);
        }

        return results;
    }

    private static async Task<List<string>> CollectResponses(Func<IChatClient> clientFactory)
    {
        var responses = new List<string>();
        foreach (var prompt in Prompts)
        {
            var client = clientFactory();
            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, "You are a helpful coding coach."),
                new(ChatRole.User, prompt)
            };
            var response = await client.GetResponseAsync(messages);
            responses.Add(response.Text ?? string.Empty);
        }
        return responses;
    }

    private static double AverageRating(Dictionary<string, EvaluationResult> results)
    {
        var ratings = results.Values
            .Where(r => r.Rating.HasValue)
            .Select(r => (double)r.Rating!.Value);
        return ratings.Any() ? ratings.Average() : 0;
    }

    private static IChatClient GetBaselineClient()
    {
        return CreateClient(
            Environment.GetEnvironmentVariable("BASELINE_DEPLOYMENT") ?? "gpt-4o-mini");
    }

    private static IChatClient GetCandidateClient()
    {
        return CreateClient(
            Environment.GetEnvironmentVariable("CANDIDATE_DEPLOYMENT") ?? "gpt-4o");
    }

    private static IChatClient CreateClient(string deployment)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();
    }

    private static IChatClient CreateJudgeClient()
    {
        return CreateClient(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini");
    }
}

