using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Compare-mode evaluations: runs the same scenarios against two model
/// configurations and compares quality scores side-by-side.
/// </summary>
public class CompareEval
{
    private static readonly string ReportDir =
        Path.Combine(Path.GetTempPath(), "MyApp.Eval", "compare-reports");

    private static readonly string[] Prompts =
    [
        "Explain dependency injection in one paragraph.",
        "What are the SOLID principles?",
        "Write a simple C# record type example."
    ];

    [Fact]
    public async Task Baseline_vs_candidate_quality_comparison()
    {
        var baselineResults = await RunSuite("baseline", GetBaselineClient);
        var candidateResults = await RunSuite("candidate", GetCandidateClient);

        // Both suites must produce results for all prompts
        Assert.Equal(Prompts.Length, baselineResults.Count);
        Assert.Equal(Prompts.Length, candidateResults.Count);

        // Candidate should not regress below baseline
        for (int i = 0; i < Prompts.Length; i++)
        {
            var baselineScore = AverageRating(baselineResults[i]);
            var candidateScore = AverageRating(candidateResults[i]);

            Assert.True(candidateScore >= baselineScore - 1,
                $"Candidate regressed on prompt {i}: baseline={baselineScore}, candidate={candidateScore}");
        }
    }

    [Fact]
    public async Task Compare_response_lengths()
    {
        var baselineResponses = await CollectResponses(GetBaselineClient);
        var candidateResponses = await CollectResponses(GetCandidateClient);

        for (int i = 0; i < Prompts.Length; i++)
        {
            // Candidate should not be excessively verbose (< 3x baseline length)
            Assert.True(candidateResponses[i].Length <= baselineResponses[i].Length * 3,
                $"Candidate response for prompt {i} is excessively long.");
        }
    }

    private static async Task<List<Dictionary<string, EvaluationResult>>> RunSuite(
        string label,
        Func<IChatClient> clientFactory)
    {
        var results = new List<Dictionary<string, EvaluationResult>>();
        var evaluators = new IEvaluator[] { new CoherenceEvaluator(), new RelevanceEvaluator() };
        var storage = new DiskBasedReportingStorage(Path.Combine(ReportDir, label));
        var config = new ReportingConfiguration(evaluators, CreateJudgeClient, storage);

        foreach (var prompt in Prompts)
        {
            var scenario = new ChatScenario($"{label}-{prompt[..20]}")
            {
                ChatMessages =
                [
                    new ChatMessage(ChatRole.System, "You are a helpful coding coach."),
                    new ChatMessage(ChatRole.User, prompt)
                ]
            };

            await using var reporter = await ReportingChatClient.CreateAsync(config, scenario);
            var client = clientFactory();
            var response = await client.GetResponseAsync(scenario.ChatMessages);
            var evalResult = await reporter.EvaluateAsync(response);
            results.Add(evalResult);
        }

        return results;
    }

    private static async Task<List<string>> CollectResponses(Func<IChatClient> clientFactory)
    {
        var responses = new List<string>();
        foreach (var prompt in Prompts)
        {
            var client = clientFactory();
            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, "You are a helpful coding coach."),
                new(ChatRole.User, prompt)
            };
            var response = await client.GetResponseAsync(messages);
            responses.Add(response.Text ?? string.Empty);
        }
        return responses;
    }

    private static double AverageRating(Dictionary<string, EvaluationResult> results)
    {
        var ratings = results.Values
            .Where(r => r.Rating.HasValue)
            .Select(r => (double)r.Rating!.Value);
        return ratings.Any() ? ratings.Average() : 0;
    }

    private static IChatClient GetBaselineClient()
    {
        return CreateClient(
            Environment.GetEnvironmentVariable("BASELINE_DEPLOYMENT") ?? "gpt-4o-mini");
    }

    private static IChatClient GetCandidateClient()
    {
        return CreateClient(
            Environment.GetEnvironmentVariable("CANDIDATE_DEPLOYMENT") ?? "gpt-4o");
    }

    private static IChatClient CreateClient(string deployment)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();
    }

    private static IChatClient CreateJudgeClient()
    {
        return CreateClient(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini");
    }
}
"}

